toolCalls.commandLine:
python -c "import subprocess,pathlib; ref=pathlib.Path('REFERENCE_BINARY.txt').read_text().strip(); cases=['ls | get name | to json -r','ls -a | get name | to json -r','ls | get name | each {|x| $x | path basename } | to json -r'];
for c in cases:
 p=subprocess.run([ref,'-c',c],capture_output=True); print('CASE',c); print(p.returncode, p.stdout.decode(errors='replace'), p.stderr.decode(errors='replace')[:200])"

